#pragma once
#include "kstationMidiEventTask.h"
#include "kstationVoiceAllocationTask.h"
#include "kstationControllerVoiceReleaseDspTask.h"
#include <optional>
namespace kstation {
class ControllerVoiceReleaseTask final {
 using T=MidiVoiceReleaseTask;using S=T::Stage;using V=VoiceAddressTask;
public:
 using Child=T::Child;ControllerVoiceReleaseTask(uint8_t part,uint8_t note):task_(part,note){}bool complete()const{return task_.complete();}bool awaitingChild()const{return task_.awaitingChild()&&!voice_&&(!dsp_||dsp_->awaitingDsp());}Child child()const{return task_.child();}uint32_t voice()const{return task_.voice();}bool resume(Child c){return awaitingChild()&&c==task_.child()&&(dsp_?dsp_->resumeDsp():task_.resume(c));}bool dspWrite()const{return dsp_&&dsp_->isWrite();}uint16_t dspAddress()const{return dsp_?dsp_->address():0;}
 bool stackWrites()const{if(dsp_)return dsp_->stackWrites();if(voice_)return false;auto s=task_.stage();return s==S::SaveCount||s==S::SaveKey||s==S::VoiceAddress||s==S::DeviceVoice||s==S::ReleaseVoice;}
 unsigned nextClocks(int previous=-1)const{if(dsp_)return dsp_->nextClocks();if(voice_){V::Credits c{3,7};return voice_->nextClocks(c);}auto s=task_.stage();uint32_t ra=0,wa=0;unsigned rn=0,wn=0;access(ra,rn,wa,wn);switch(s){case S::Complete:case S::AwaitChild:return 0;case S::SaveCount:case S::SaveKey:case S::RestoreKey:case S::RestoreCount:return 6;case S::VoiceAddress:case S::DeviceVoice:case S::ReleaseVoice:return 10;case S::Return:return 7;case S::SelectCount:return 8;case S::BindLowState:return 6;case S::ReadPatch:case S::WriteState:return 15+bus(rn?ra:wa,rn?rn:wn,rn?-1:previous);case S::ReadState:case S::ReadVoicePart:case S::ReadVoiceNote:case S::ReadPatchFlags:case S::WriteDeferred:return 12+bus(rn?ra:wa,rn?rn:wn,rn?-1:previous);case S::WritePart:case S::ReadPart:case S::WriteIndex:case S::ReadCount:case S::ReadSustain:case S::ReadIndex:case S::WriteNextIndex:return 9+bus(rn?ra:wa,rn?rn:wn,rn?-1:previous);default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(dsp_){auto used=dsp_->advanceBefore(cost,read,write);if(dsp_->complete()){auto c=task_.child();dsp_.reset();task_.resume(c);}return used;}if(voice_){V::Credits c{3,7};auto used=voice_->advanceBefore(cost,c,[&](){return read(0xd023,1,cost);});if(voice_->complete()){auto v=voice_->address();voice_.reset();task_.resume(Child::VoiceAddress,v);}return used;}uint32_t ra=0,wa=0;unsigned rn=0,wn=0;access(ra,rn,wa,wn);bool ok=task_.advance([&](T::Read){return read(ra&0xffffff,rn,cost);},[&](T::Write,uint32_t v){write(wa&0xffffff,v,wn,cost);});if(!ok)return 0;if(task_.awaitingChild()&&task_.child()==Child::VoiceAddress)voice_.emplace();else if(task_.awaitingChild()&&task_.child()==Child::DeviceVoice)dsp_.emplace(ControllerVoiceReleaseDspTask::Kind::Select);else if(task_.awaitingChild()&&task_.child()==Child::ReleaseVoice)dsp_.emplace(ControllerVoiceReleaseDspTask::Kind::Gate);return cost;}
private:
 static unsigned bus(uint32_t a,unsigned n,int previous){unsigned c=0;for(unsigned i=0;i<n;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((previous&1)||x!=uint32_t(previous|1))c+=x<0x400000?3:1;previous=int(x);}else{c+=x>=0xffffa0?1:3;previous=-1;}}return c;}
 void access(uint32_t&ra,unsigned&rn,uint32_t&wa,unsigned&wn)const{switch(task_.stage()){case S::ReadPart:ra=0xd028;rn=1;break;case S::ReadCount:ra=0xd022;rn=1;break;case S::ReadState:ra=task_.voice()+8;rn=2;break;case S::ReadVoicePart:ra=task_.voice()+4;rn=1;break;case S::ReadVoiceNote:ra=task_.voice()+5;rn=1;break;case S::ReadPatch:ra=task_.voice();rn=4;break;case S::ReadPatchFlags:ra=task_.patch()+0x58;rn=1;break;case S::ReadSustain:ra=0xcc01;rn=1;break;case S::ReadIndex:ra=0xd023;rn=1;break;case S::WritePart:wa=0xd028;wn=1;break;case S::WriteIndex:case S::WriteNextIndex:wa=0xd023;wn=1;break;case S::WriteDeferred:wa=task_.voice()+17;wn=1;break;case S::WriteState:wa=task_.voice()+8;wn=4;break;default:break;}}
 T task_;std::optional<V>voice_{};std::optional<ControllerVoiceReleaseDspTask>dsp_{};
};
}
